<script lang="ts">
 import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';export let state:WorkbenchState;let contextId='local';let current='/';let items:any[]=[];let route:any;let error='';let loading=false;let cursor:string|null=null;let generation=0;
 async function load(path=current,append=false){const token=++generation,requestedContext=contextId;loading=true;error='';try{const suffix=append&&cursor?`&cursor=${encodeURIComponent(cursor)}`:'';const page=await api<any>(`/api/files?contextId=${encodeURIComponent(requestedContext)}&path=${encodeURIComponent(path)}&limit=250${suffix}`);if(token!==generation||requestedContext!==contextId)return;current=path;items=append?[...items,...page.items]:page.items;cursor=page.nextCursor;route=page.route;}catch(value){if(token!==generation)return;error=(value as Error).message;if(!append)items=[];}finally{if(token===generation)loading=false;}}
 let clickTimer:number|undefined;function open(item:any,pinned=false){if(item.type==='directory'){if(!pinned)void load(item.path);return;}if(item.type==='file')window.dispatchEvent(new CustomEvent('atlas:open-file',{detail:{contextId,path:item.path,pinned}}));}function click(item:any){if(item.type==='directory'){open(item);return;}clearTimeout(clickTimer);clickTimer=window.setTimeout(()=>open(item),180);}function doubleClick(item:any){clearTimeout(clickTimer);open(item,true);}
 function up(){if(current==='/')return;void load(current.split('/').slice(0,-1).join('/')||'/');}
 onMount(()=>{const unsubscribe=state.subscribe(value=>{if(value.contextId!==contextId){clearTimeout(clickTimer);generation++;contextId=value.contextId;current='/';items=[];route=undefined;cursor=null;loading=true;void load('/');}});void load();return()=>{generation++;clearTimeout(clickTimer);unsubscribe();};});
</script>
<aside class="explorer"><header><div><strong>FILESYSTEM</strong><span>{contextId}</span></div><button onclick={()=>load()}>↻</button></header><div class="pathbar"><button onclick={up} disabled={current==='/'}>↑</button><span title={current}>{current}</span></div>{#if route}<div class="route-chip">{route.kind} · {route.effectiveIdentity} · {route.privilege}</div>{/if}{#if error}<div class="panel-error">{error}</div>{/if}<div class="file-list" aria-busy={loading}>{#each items as item}<button class="file-row" disabled={loading} ondblclick={()=>doubleClick(item)} onclick={()=>click(item)}><span>{item.type==='directory'?'▸':item.type==='symlink'?'↗':'·'}</span><b>{item.name}</b><small>{item.type==='file'?`${item.bytes} B`:item.type}</small></button>{/each}{#if cursor}<button class="load-more" disabled={loading} onclick={()=>load(current,true)}>Load more</button>{/if}</div></aside>
